recipes.code:
{
  "inputs": [
    {
      "id": "oa-api-key",
      "type": "promptString",
      "description": "OpenAgenda API key (the stdio credential — a least-privilege/read key is advised). The hosted remote uses OAuth instead.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@openagenda/mcp@1.3.2"
      ],
      "env": {
        "OA_API_KEY": "${input:oa-api-key}",
        "OA_BASE_URL": "<oa-base-url>",
        "OA_EXECUTOR": "<oa-executor>",
        "OA_LOCAL_NO_SANDBOX": "<oa-local-no-sandbox>"
      }
    }
  }
}
